import{_ as a,o as s,c as e,a2 as l}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"CDS G/H (Day 2) - Systemtap/LTTng static markers (update)","description":"","frontmatter":{"title":"CDS G/H (Day 2) - Systemtap/LTTng static markers (update)","date":"2014-06-26T00:00:00.000Z","updated":"2014-06-26T00:00:00.000Z","tags":["Ceph","监控","性能优化","系统追踪","分布式存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_G_H_Day_2_-_Systemtap_LTTng_static_markers_update.md","filePath":"posts/2014/CDS_G_H_Day_2_-_Systemtap_LTTng_static_markers_update.md","lastUpdated":1780459816000}'),i={name:"posts/2014/CDS_G_H_Day_2_-_Systemtap_LTTng_static_markers_update.md"};function r(p,t,o,n,_,c){return s(),e("div",null,[...t[0]||(t[0]=[l('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： [请填写会议时间]</p><p><strong>参会人员</strong>： [请填写参会人员名单]</p><p><strong>会议主题</strong>： Ceph 分布式存储系统监控与性能优化</p><p><strong>会议内容</strong>：</p><p><strong>1. 监控与性能优化路径</strong></p><ul><li>会议讨论了并行进行的两个路径：Adam 和其他人员尝试集成 lttng，同时其他人专注于收集数据以便通过 ops 路径获取操作详细信息（写入、读取、权限等）。</li><li>使用 system tap 进行系统追踪，主要目的是追踪资源竞争并将其与操作关联起来。目标是确保 OSD 中的每个互斥锁在获取时都提供操作信息，以便在日志期间关联资源。</li><li>目前的工作集中在创建一些超级类以减少混乱，并确保代码中的 Tracepoints 注释能够通用化。</li></ul><p><strong>2. Tracepoints 与系统追踪</strong></p><ul><li>system tap 和 lttng 都提供了 Tracepoints，可用于在代码中插入追踪信息。</li><li>system tap 在 OSD stap 中用 track_mutex 替换了 mutex，并要求 lock 和 unlock 方法提供 trace_op。</li><li>lttng 具有热传递代码的能力，可以在 SE 端使用编译后的本地代码进行追踪。</li><li>Tracepoints 的格式相似，包括 tracepoint 名称和一系列未解释的信息。</li></ul><p><strong>3. 客户端追踪</strong></p><ul><li>Noah 正在研究 Oco 路径中时间消耗的原因，以及操作为什么耗时如此之长。</li><li>Adam 正在研究客户端追踪，目标是创建一个标准的客户端库构建版本，能够订阅 Trace 事件流并捕获工作负载的追踪信息。</li><li>可以使用 system tap 或 lttng 进行客户端追踪，并选择合适的格式写入数据。</li></ul><p><strong>4. 调试与优化</strong></p><ul><li>需要关注两条并行路径中的补丁，确保它们不会在合并时产生冲突。</li><li>通过收集不同客户的追踪数据，可以分析工作负载特征，并在测试集群上进行优化。</li><li>可以利用其他工具和技术，例如将文件系统追踪转换为 fio 配置文件，以模拟工作负载。</li></ul><p><strong>5. 其他</strong></p><ul><li>Mam 正在尝试启动 BlueJeans 会议系统。</li><li>Min 建议讨论 copy on read 克隆。</li></ul><p><strong>行动计划</strong>：</p><ul><li>Adam 和 Noah 继续研究追踪和性能优化。</li><li>Mam 尝试解决 BlueJeans 会议系统的问题。</li><li>Min 提出讨论 copy on read 克隆。</li></ul><p><strong>备注</strong>：</p><ul><li>会议中提到的关键技术包括：lttng、system tap、Tracepoints、OSD stap、mutex、track_mutex、SE、PG、RBD、fio 等。</li></ul>',19)])])}const u=a(i,[["render",r]]);export{m as __pageData,u as default};
